'use strict';
const $=s=>document.querySelector(s), E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const REPO='https://github.com/MarkJiang-maji/chen-research-site';
const ARCHIVE='https://github.com/MarkJiang-maji/chen-liquidity-research';
const FILE=p=>'/api/workspace/file?path='+encodeURIComponent(p);
const PATH='workstation/content.json', REPORTPATH='workstation/reports.json';
let C=SEED.content, R=SEED.reports, remoteHash={}, canEdit=false, route='', filter='all', docTab='guide', busy=false, mountedAudio=null, pdfPage=1, pdfZoom=100, paperLayout='split', explainOn=localStorage.getItem('chen-explain')!=='off';
const icons={home:'M3 10l9-7 9 7v10H3z M9 20v-7h6v7',learn:'M3 4h7l2 2 2-2h7v15h-7l-2 2-2-2H3z M12 6v15',paper:'M5 3h10l4 4v14H5z M14 3v6h5 M8 12h8 M8 16h8',docs:'M3 5h7l2 3h9v12H3z',experiment:'M8 3h8 M10 3v7L4 20h16l-6-10V3 M8 15h8',reports:'M3 4h18v13H3z M12 17v4 M8 21h8 M7 8h10 M7 12h6',library:'M4 3h4v18H4z M11 3h4v18h-4z M17 5l3-1 4 16-3 1z'};
const icon=k=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[k]||icons.docs}"/></svg>`;
const badge=(text,kind='')=>`<span class="badge ${kind}">${E(text)}</span>`;
const btn=(text,href,kind='')=>`<a class="button ${kind}" href="${E(href)}">${E(text)}</a>`;
const paras=v=>(Array.isArray(v)?v:[v]).filter(Boolean).map(x=>typeof x==='string'?`<p>${E(x).replace(/\n/g,'<br>')}</p>`:block(x)).join('');
const list=v=>`<ul>${(v||[]).map(x=>`<li>${typeof x==='string'?E(x):block(x)}</li>`).join('')}</ul>`;
function block(v){if(v==null)return '';if(typeof v==='string')return E(v).replace(/\n/g,'<br>');if(typeof v==='number'||typeof v==='boolean')return E(v);const labels={question:'要回答的問題',inputs:'使用資料',method:'如何檢驗',metrics:'衡量指標',supports:'可以支持',does_not_support:'不能支持',next:'下一步',sample:'資料期間',quotes:'報價數',one_factor:'單因子',two_factor:'兩因子',three_factor:'三因子',unit:'單位',meaning:'怎麼解讀',type:'證據類型',label:'原文定位'};if(Array.isArray(v)){if(v.length&&v.every(x=>x&&typeof x==='object'&&!Array.isArray(x)&&Object.values(x).every(y=>['string','number','boolean'].includes(typeof y)))&&v[0].sample){const keys=Object.keys(v[0]);return `<div class="tablewrap"><table class="table"><thead><tr>${keys.map(k=>`<th>${E(labels[k]||k)}</th>`).join('')}</tr></thead><tbody>${v.map(x=>`<tr>${keys.map(k=>`<td>${E(x[k])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}return list(v);}return Object.entries(v).filter(([k])=>!['id','url','pdf','pdf_path'].includes(k)).map(([k,x])=>`<div>${['title','heading','name','section'].includes(k)?`<h3>${E(x)}</h3>`:k==='status'?`<p>${badge(x,'blue')}</p>`:typeof x==='string'||typeof x==='number'?`<p>${labels[k]?`<strong>${labels[k]}：</strong>`:''}${E(x)}</p>`:block(x)}</div>`).join('')}
const rich=(s)=>E(s??'').replace(/^### (.+)$/gm,'<h3>$1</h3>').replace(/^## (.+)$/gm,'<h2>$1</h2>').replace(/^# (.+)$/gm,'<h2>$1</h2>').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\n\n/g,'</p><p>').replace(/\n/g,'<br>');
function heading(tag,title,sub,actions=''){return `<header class="pagehead"><div><div class="eyebrow">${E(tag)}</div><h1>${E(title)}</h1><p>${E(sub)}</p></div>${actions}</header>`}
function toast(s){$('.toast')?.remove();const d=document.createElement('div');d.className='toast';d.setAttribute('role','status');d.textContent=s;document.body.append(d);setTimeout(()=>d.remove(),5500)}
function nav(){const links=[['home','研究總覽'],['learn','從零開始'],['manuscript','論文主線'],['docs','研究文件'],['experiments','實驗紀錄'],['reports','研究報告'],['library','來源與文獻'],['terms','名詞隨身讀']];return `<aside class="sidebar"><a class="brand" href="#/home" style="color:inherit;text-decoration:none"><span class="brand-icon">c<span>·</span></span><span><strong>Chen Research</strong><small>陳教授研究工作站</small></span></a><div class="navlabel">一個問題，一條證據鏈</div><nav>${links.map(([id,label])=>`<a class="navlink ${route===id?'active':''}" href="#/${id}">${icon(id==='manuscript'?'paper':id==='experiments'?'experiment':id)}${label}</a>`).join('')}</nav><div class="sidefoot"><span class="statusdot"></span>雲端研究工作站<br><span style="font-size:10px">資料與報告可在線閱讀、編輯<br>研究更新 · 2026.10.21</span><div style="margin-top:15px"><a href="${REPO}" target="_blank" rel="noopener">網站 GitHub ↗</a></div></div></aside>`}
function shell(body){document.body.className='';$('#app').innerHTML=`<div class="shell">${nav()}<div class="workspace"><header class="topbar"><span class="crumb">Chen Research <span style="margin:0 12px;color:#b8b8bf">/</span> ${E({home:'總覽',learn:'學習',manuscript:'論文',docs:'文件',experiments:'實驗',reports:'報告',library:'來源'}[route]||'工作站')}</span><div class="topright"><button class="aid-toggle" id="explainToggle" aria-pressed="${explainOn}">名詞解釋 <span>${explainOn?'開':'關'}</span></button><button class="button light small" id="loginBtn">${canEdit?'已登入 · 編輯':'登入編輯'}</button></div></header><main class="page">${body}</main><footer class="page-footer"><span>Chen Research · 從問題走向證據</span><a href="#/terms">遇到不懂的詞？隨手查 →</a></footer></div></div>`;$('#explainToggle').onclick=()=>{explainOn=!explainOn;localStorage.setItem('chen-explain',explainOn?'on':'off');renderReadingPosition()};$('#loginBtn').onclick=()=>canEdit?editMenu():login();document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editCurrent(b.dataset.edit));}
function signalArt(){return `<svg viewBox="0 0 410 245" role="img" aria-label="從含噪觀測到狀態估計，再到經濟驗證的研究流程示意，非市場數據"><defs><linearGradient id="fade" x2="0" y2="1"><stop stop-color="#c1deff" stop-opacity=".6"/><stop offset="1" stop-color="#eaf3ff" stop-opacity="0"/></linearGradient></defs><rect x="0" y="0" width="410" height="245" rx="17" fill="#f8fafc"/><path d="M24 70H386 M24 120H386 M24 170H386" stroke="#e9edf3"/><path d="M25 155l12-35 10 42 10-66 10 48 10-13 10 22 10-66 10 40 10-42 10 32 10-58 10 33 10 14 10-31 10 23 10-40 10 14 10-37 10 40 10-22 10 6 10-32 10 26 10-49 10 31 10-19 10 28 10-48 10 29 10-7 10 13 10-40 10 9 10-20 10 15" fill="none" stroke="#c6cdd7" stroke-width="1.4"/><path d="M25 148C60 148 74 136 100 126S145 114 177 103 213 95 244 89 270 79 305 75 349 61 385 54V194H25Z" fill="url(#fade)"/><path d="M25 148C60 148 74 136 100 126S145 114 177 103 213 95 244 89 270 79 305 75 349 61 385 54" fill="none" stroke="#0071e3" stroke-width="3"/><circle cx="385" cy="54" r="5" fill="#0071e3"/><text x="26" y="27" font-size="9" fill="#8b929c" letter-spacing="1.2">OBSERVATION → STATE → EVIDENCE</text><text x="26" y="223" font-size="10" fill="#a2a6ad">灰線：含噪觀測</text><text x="168" y="223" font-size="10" fill="#0071e3">藍線：狀態估計（示意）</text></svg>`}
function home(){return `<section class="opening"><div class="eyebrow">CHEN RESEARCH / 研究手記 001</div><div class="opening-title"><h1>先看懂問題。<br><span>再一起找到答案。</span></h1><p>一條起伏的成交量曲線，怎麼走成<br class="desktop-only">一個值得研究的金融問題？</p></div><div class="actions">${btn('從教授的問題開始 ↓','#story','dark')}${btn('繼續研究 →','#/manuscript','glass')}</div><div class="opening-art" data-verbatim>${researchMap()}</div><div class="opening-caption"><span>從看得到的數字，追問看不到的原因。</span><span>原始資料 → 模型 → 實驗 → 論文</span></div></section><section id="story" class="story-intro"><div class="eyebrow">01 / 故事從兩張圖開始</div><h2>「先讓成交量清楚一點，<br>再看它跟價格有什麼關係。」</h2><p>這是教授原訊息的中文意譯。他看了 MS、GS 的價量圖，想把肉眼看見的關係變成可量化的問題。這是我們的起點。</p><div class="stock-pair" data-verbatim><a href="#/docs/originals"><b>MS</b><span>Morgan Stanley<br>摩根士丹利 · 股票代號</span><i>↗</i></a><a href="#/docs/originals"><b>GS</b><span>Goldman Sachs<br>高盛 · 股票代號</span><i>↗</i></a></div><a class="text-link" href="#/docs/originals">對照原始訊息、圖與錄音 →</a></section><section class="story-chapters"><div class="sectionhead"><div><div class="eyebrow">02 / 為什麼不能直接把線變平？</div><h2>一根尖峰，可能是兩件不同的事。</h2></div></div><div class="fork-diagram"><div class="fork-source"><span>今天看到</span><strong>成交量突然變大</strong><svg viewBox="0 0 250 75" aria-label="成交量突然升高的教學示意"><path d="M5 60L45 58L80 61L110 12L140 60L175 58L210 60L245 59"/></svg></div><div class="fork-branches"><div><span class="dot amber"></span><h3>讀數出了問題？</h3><p>例如資料異常。我們希望減少它的影響。</p></div><div><span class="dot teal"></span><h3>市場真的變了？</h3><p>例如重大事件。我們反而想保留這份訊息。</p></div></div></div><p class="bridge-text">所以目標不是「越平滑越好」，而是<strong>減少壞讀數，同時保留真變化</strong>。更難的是：只看一條曲線，有時根本分不清兩者。</p><a class="text-link" href="#/learn/L3">先用一個小例子理解濾波 →</a></section><section class="research-story"><div class="eyebrow">03 / 從直覺走向可以被推翻的研究</div><h2>我們每往前一步，<br>都要多回答一個「為什麼」。</h2>${storySteps()}</section><section class="current-chapter"><div class="current-copy"><div class="eyebrow">現在走到這裡 / 第七個實驗 E7</div><h2>同樣的價量，<br>仍可能有不同的折價。</h2><p>這次接上教授提供的定價公式：讓價量基準跟著候選狀態改變，41 組答案都能重建相同的價格與成交量。</p><p>所以還要問：哪些校準參數必須先有可信的約束？</p>${btn('看實驗怎麼設計、得到什麼 →','#/experiments/e7','dark')}</div><div class="current-evidence"><span class="badge">已執行 · 41 組定價等價解</span><h3>價量擬合，仍不足以挑出真相。</h3><div class="evidence-value"><strong>5.41–15.59</strong><span>等價解的資產折價範圍（合成單位）</span></div><p>讓價量基準的斜率 b 變動時，不同狀態可產生相同讀數；有噪音時，固定正確 b 也常碰到參數界。</p><div class="evidence-limit">證據邊界：固定作者草稿公式的合成診斷。原圖、動態與市場估值仍未完成。</div></div></section><div class="sectionhead"><div><div class="eyebrow">接下來，選一條閱讀路徑</div><h2>你想先弄懂，還是繼續深挖？</h2></div></div><div class="path-grid"><a href="#/learn"><span>01 · 第一次接觸</span><h3>從生活例子學起</h3><p>價格、成交量、濾波與公式；一次只學一件事。</p><b>進入入門課 →</b></a><a href="#/docs/chen-scott-2003"><span>02 · 把論文讀懂</span><h3>原文與導讀，一起看</h3><p>左邊講解，右邊原文；每段推理都能回到來源。</p><b>打開雙欄閱讀 →</b></a><a href="#/manuscript"><span>03 · 作為研究者</span><h3>檢查論文的證據鏈</h3><p>假設、比較方法、負結果與下一個檢驗。</p><b>沿著研究主線 →</b></a></div><div class="sectionhead"><div><div class="eyebrow">RESEARCH MEETINGS</div><h2>每個階段，都說清楚做了什麼。</h2></div><a class="text-link" href="#/reports">全部報告 →</a></div><div class="grid2">${R.filter(r=>r.kind!=='工作流程導覽').slice(0,2).map(reportCard).join('')}</div><details class="abstract-fold"><summary>想看學術版本？展開研究摘要</summary><div class="prose">${paras(C.home.abstract)}<button class="button light small" data-edit="home">編輯研究摘要</button></div></details>`}
function reportCard(r){return `<article class="card reportcard"><a class="reportcover" style="color:inherit;text-decoration:none" href="?meeting=${encodeURIComponent(r.id)}" target="_blank" rel="noopener"><span class="rindex">MEETING ${E(r.date)} · ${r.slides.length} 頁</span><h3>${E(r.title)}</h3><span style="font-size:11px;color:var(--blue)">逐頁投影片 ＋ 完整講稿 ↗</span></a>${badge(r.kind||'研究進度',r.id==='e6'?'blue':'')}<p>${E(r.summary)}</p><div class="actions">${btn('開啟報告 ↗','?meeting='+encodeURIComponent(r.id),'light small')} <a class="subtle" href="#/reports/${encodeURIComponent(r.id)}">閱讀摘要</a></div></article>`}
function manuscript(){const h=C.home;return heading('PAPER IN PROGRESS','論文主線','一份會隨證據更新的研究草稿。已完成、待驗證與尚未執行分開標示。',`<button class="button light" data-edit="home">編輯主線</button>`)+`${researchReasoning()}<div class="reader-grid"><article class="reader prose"><div class="eyebrow">WORKING TITLE · 暫定</div><h2 style="margin-top:8px">從噪音成交量到可識別的流動性狀態</h2><div class="callout">${E(h.question)}</div><h2 id="abstract">摘要</h2>${paras(h.abstract)}<h2 id="intro">Introduction：為什麼值得研究</h2>${paras(h.introduction)}<h2 id="objectives">研究目標</h2>${list(h.objectives)}<h2 id="outline">預計論文架構</h2>${block(h.paper_outline)}<h2 id="contribution">貢獻與已知工作的差異</h2>${block(h.contributions)}<h2 id="ladder">實驗如何支撐論文</h2>${block(h.experiment_ladder)}<h2 id="limits">目前不能聲稱什麼</h2>${list(h.limitations)}<h2 id="stop">停止與轉向條件</h2>${list(h.stop_rules)}<h2 id="prompt">下一輪研究 Prompt</h2><div style="font-size:13px;white-space:pre-wrap">${E(C.research_prompt.text)}</div><div class="sourcestrip">教授原意、研究者提案、文獻事實與實驗結果分別保存；新方法尚未成立。</div></article><aside class="toc"><strong>這篇論文的骨架</strong>${[['abstract','摘要'],['intro','介紹'],['objectives','研究目標'],['outline','章節架構'],['contribution','貢獻'],['ladder','實驗階梯'],['limits','限制'],['stop','停止規則'],['prompt','研究 Prompt']].map(([id,t])=>`<a href="#${id}" data-anchor="${id}">${t}</a>`).join('')}<hr style="border:0;border-top:1px solid var(--line)"><a href="#/experiments">查看實驗證據 →</a></aside></div>`}
function learning(id){const lessons=C.lessons;const l=lessons.find(x=>x.id===id)||lessons[0],n=lessons.indexOf(l);return heading('LEARN THE FOUNDATIONS','從零開始，一次弄懂一件事。','不用先懂金融。每一課都從例子開始，再走向公式與我們的研究。')+`<nav class="lessonnav">${lessons.map((x,i)=>`<a href="#/learn/${E(x.id)}" class="${x===l?'active':''}">${String(i+1).padStart(2,'0')} ${E(x.title)}</a>`).join('')}</nav><div class="reader-grid"><article class="reader prose"><div class="eyebrow">LESSON ${String(n+1).padStart(2,'0')} / ${lessons.length}</div><h2 style="margin-top:8px">${E(l.title)}</h2>${paras(l.intuition)}<h2>用一個例子想清楚</h2><div class="callout">${block(l.example||l.numeric_example)}</div>${lessonVisual(l)}<h2>公式不是用來嚇人的</h2><div class="formula">${typeof l.formula==='string'?E(l.formula):block(l.formula)}</div>${l.symbols?`<details open><summary>每個符號是什麼意思</summary><div class="tablewrap"><table class="table">${Object.entries(l.symbols).map(([k,v])=>`<tr><td><strong>${E(k)}</strong></td><td>${E(v)}</td></tr>`).join('')}</table></div></details>`:''}<h2>這個想法從哪裡來</h2>${block(l.history)}<h2>容易誤會的地方</h2>${block(l.pitfalls)}<h2>和我們的論文有什麼關係</h2>${paras(l.relation_to_research)}<p><button class="button light small" data-edit="lesson:${E(l.id)}">編輯這一課</button></p><details><summary>停一下，檢查自己懂了嗎？</summary><p>${E(l.check_question||l.check?.question||l.question)}</p><details><summary>看解答</summary>${block(l.answer||l.check_answer||l.check?.answer)}</details></details><div style="display:flex;justify-content:space-between;margin-top:25px">${n>0?btn('← 上一課','#/learn/'+lessons[n-1].id,'light'):''}${n<lessons.length-1?btn('下一課 →','#/learn/'+lessons[n+1].id,'blue'):btn('開始讀教授的問題 →','#/docs/originals','blue')}</div></article><aside class="toc"><strong>這一課的學習路徑</strong><p>生活直覺<br>↓<br>數字例子<br>↓<br>公式與符號<br>↓<br>回到研究問題</p><button class="button light small" data-edit="lesson:${E(l.id)}">編輯這一課</button><p class="subtle">教學例子皆為示意，與市場實證結果分開。</p></aside></div>`}
function documentIndex(){return heading('RESEARCH DOCUMENTS','每一份資料，都知道為什麼讀。','原始構想與核心論文是研究主線的起點。PDF、錄音與逐字稿直接在線閱讀。')+`<a class="cardlink" href="#/docs/originals"><div class="hero" style="min-height:210px"><div><span class="badge blue">從這裡開始</span><h2 style="font-size:27px">教授原始問題與會談資料</h2><p>英文對話、MS（摩根士丹利）／GS（高盛）兩張圖、26 分鐘錄音與帶時間戳逐字稿。先看他實際說了什麼。</p><span style="font-size:12px;color:var(--blue)">開啟來源導讀 →</span></div><div class="hero-visual">${signalArt()}</div></div></a><div class="sectionhead"><h2>兩篇核心論文</h2><small>各有白話導讀、原文與逐頁 meeting</small></div><div class="grid2">${C.papers.map((p,i)=>`<article class="card"><div class="eyebrow">CORE PAPER 0${i+1} · ${E(p.year)}</div><h3 style="font-size:22px">${i===0?'看見利率背後的隱藏因子':'把交易限制變成流動性折價'}</h3><p>${E(p.title)}</p><p>${E(p.authors)}</p><div class="statusline">${badge(i===0?'估計方法':'定價目標','blue')}<span>原文 · 導讀 · 研究影響</span></div>${btn('閱讀導讀','#/docs/'+p.id,'light small')} ${btn('Meeting ↗','?meeting='+p.id,'ghost small')}</article>`).join('')}</div><div class="sectionhead"><h2>方法與證據文件</h2></div><div class="card">${[['研究執行 Prompt','把教授原意轉成可執行與可否證的研究規格','research/RESEARCH_PROMPT.md'],['E5 方法基準與失敗案例','完整保留 26.57% 的適用條件與失敗情境','research/FILTER_HOLDOUT_FINDINGS.md'],['公式重現與未解差異','獨立計算一致，不代表所有原圖與實證已重現','research/CHEN2015_REPRODUCTION.md']].map(([t,s,p])=>`<div class="row"><div class="grow"><h3>${t}</h3><p>${s}</p></div><a href="#/read/${encodeURIComponent(p)}">在線讀 →</a></div>`).join('')}</div>`}
function paper(id){const p=C.papers.find(x=>x.id===id);if(!p)return documentIndex();const i=C.papers.indexOf(p),pdf=i===0?'jrefe_galley.pdf':'JFI-CHEN.pdf';pdfPage=Math.min(Math.max(pdfPage,1),p.page_images.length);const activeSection=sectionForPage(p,pdfPage);return `<header class="paper-heading"><a class="text-link" href="#/docs">← 研究文件</a><div class="eyebrow">核心論文 ${i+1} / ${p.year} / ${p.pdf_page_count} 頁</div><h1>${i===0?'用多支讀數，看見隱藏的利率。':'不能隨時賣，今天該少付多少？'}</h1><p>${E(p.one_sentence)}</p><details class="paper-citation"><summary>論文題名與來源</summary><p data-verbatim>${E(p.title)}<br>${E(p.authors.join('、'))} · ${E(p.venue)}<br>${E(p.page_note)}</p></details></header><div class="workbench-toolbar"><div class="segmented" aria-label="閱讀版面">${[['split','導讀 ＋ 原文'],['guide','專心讀導讀'],['original','專心讀原文']].map(([k,v])=>`<button data-layout="${k}" aria-pressed="${paperLayout===k}" class="${paperLayout===k?'active':''}">${v}</button>`).join('')}</div><span class="subtle">點導讀頁碼，右邊跟著翻頁</span></div><section class="paper-workbench layout-${paperLayout}" data-paper-id="${E(p.id)}"><article class="guide-pane"><div class="pane-header"><span><i class="dot teal"></i> 白話導讀</span><button class="button ghost small" data-edit="paper:${E(p.id)}">編輯</button></div><div class="guide-scroll prose"><div class="guide-tabs" role="tablist" aria-label="導讀內容"><button role="tab" aria-selected="${docTab!=='impact'}" data-doctab="guide" class="${docTab!=='impact'?'active':''}">跟著原文讀</button><button role="tab" aria-selected="${docTab==='impact'}" data-doctab="impact" class="${docTab==='impact'?'active':''}">對本研究的影響</button></div>${docTab==='impact'?`<section class="guide-section"><div class="eyebrow">借用什麼，還缺什麼？</div><h2>這篇論文在我們的故事中做什麼</h2>${block(p.impact_on_ours)}<h2>不能直接帶過來的結論</h2>${block(p.limits)}<div class="callout">${i===0?'它給我們「從狀態算價格，再由價格估狀態」的架構；沒有直接給我們成交量的觀測式。':'它給我們流動性定價目標；將它接上即時濾波，是我們仍須建立與檢驗的部分。'}</div><a href="#/manuscript" class="text-link">回到論文主線，追查這座橋怎麼搭 →</a></section>`:`<section class="guide-section"><div class="eyebrow">讀之前，先帶著這個問題</div><h2>${i===0?'為什麼同時看不同期限？':'相同未來給付，交易限制會改變價值嗎？'}</h2><p>${E(p.beginner_entry)}</p><div class="reading-goal"><strong>這次先找三樣東西</strong><ol><li>作者想估什麼？哪些東西看不見？</li><li>作者拿哪些實際數字來約束它？</li><li>什麼證據支持結論，什麼還不行？</li></ol></div></section>${p.sections.map((s,j)=>`<section id="guide-${j}" class="guide-section ${s===activeSection?'is-current':''}" data-pages="${(s.pdf_pages||[]).join(',')}"><div class="guide-location"><span>${String(j+1).padStart(2,'0')} / 原文對照</span><div>${(s.pdf_pages||[]).map(n=>`<button data-pdf-page="${n}" aria-label="在右側閱讀原文第 ${n} 頁" class="page-chip ${n===pdfPage?'selected':''}">p.${n}</button>`).join('')}</div></div><h2>${E(s.title)}</h2><div class="guide-plain"><span class="reading-label">先用白話理解</span><p>${E(s.plain||s.text||s.body)}</p><span class="reading-label">作者為什麼這麼做？</span><p>${E(s.why||s.read_for||'')}</p></div><details class="technical-detail"><summary>進階：模型、公式與注意事項</summary>${paras(s.text||s.body)}</details>${s.read_for?`<div class="reading-cue"><strong>帶走這個重點</strong><p>${E(s.read_for)}</p></div>`:''}</section>`).join('')}<section class="guide-section"><div class="eyebrow">最後 / 判斷證據</div><h2>論文提出了什麼證據？</h2>${block(p.evidence)}<h2>哪些結論還不能借用？</h2>${block(p.limits)}<button class="button dark" data-doctab="impact">接著看：對我們研究的影響 →</button></section>`}</div></article><aside class="original-pane" aria-label="與導讀並排的原始論文"><div class="pane-header"><span><i class="dot amber"></i> 原始 PDF · 頁序 ${pdfPage}/${p.pdf_page_count}</span><a class="text-link" href="${FILE('sources/originals/'+pdf)}" target="_blank" rel="noopener" aria-label="另外開啟原始 PDF">↗</a></div><div id="pdfPanel">${pdfReaderHTML(p,pdf)}</div></aside></section><p class="reader-footnote">${E(p.page_note)} 導讀是研究者整理；右側保留原文頁面與公式排版。原論文結果與本次實驗分開標示。</p>`}
function originals(){return heading('PRIMARY SOURCES','先聽教授怎麼說。','原始檔集中在同一處。ASR 是機器辨識，原話、術語校正與研究解讀分開。')+`<div class="reader prose"><div class="eyebrow">原始英文對話 · 使用者提供</div><h2>先平滑成交量，再研究它與價格的關係</h2><blockquote data-verbatim style="margin:20px 0;border-left:3px solid #ccd5df;padding-left:22px;font-size:17px">I want to first smooth out volume and then study its correlation with price.</blockquote><p>教授已試過幾種濾波器，也正在嘗試 Kaufman 的 KAMA。他想把肉眼看見的現象變成可量化的研究，但這不等於預先指定一定要證明負相關。</p><p>原訊息中的 “but we can successfully quantify” 與上下文有疑義；保留原文，沒有擅自改成 cannot。</p><div class="split"><figure style="margin:0"><img class="media" src="${FILE('sources/originals/MS-price-volume.jpg')}" alt="教授提供的 MS 價格與成交量雙軸圖"><figcaption class="subtle">MS（Morgan Stanley，摩根士丹利）· 依使用者歸屬，原圖未標公司；精確資料定義未提供。</figcaption></figure><figure style="margin:0"><img class="media" src="${FILE('sources/originals/GS-price-volume.jpg')}" alt="教授提供的 GS 價格與成交量雙軸圖"><figcaption class="subtle">GS（Goldman Sachs，高盛）· 原圖標 GS；雙縱軸的視覺關係需要正式檢驗。</figcaption></figure></div><div class="callout">這兩張圖是研究動機。頻率、調整方式與原始序列未確認，不能從圖片直接斷言已經統計顯著。</div><h2>從錄音到研究問題</h2><p>前段討論趨勢、濾波與多維資料；後段談到「我不是 price 股票，我是 price liquidity」，以及額外信用／CDS 觀測。該句取自未人工核實的 ASR。</p><div class="audio-row"><strong>會談錄音 · 約 25 分 56 秒</strong><audio id="recording" controls preload="metadata" src="${FILE('sources/originals/陳教授金融.m4a')}"></audio><small class="subtle">點逐字稿時間可跳轉。最後辨識到約 23:39；尾段補辨識仍有疑慮。</small></div><input class="search" id="transcriptSearch" placeholder="搜尋逐字稿，例如：liquidity、filter、股票" aria-label="搜尋逐字稿"><div id="transcript">${transcriptRows('')}</div><div class="sourcestrip"><a href="#/read/${encodeURIComponent('sources/originals/professor-chat-20261013.txt')}">完整英文訊息</a> · <a href="${ARCHIVE}/tree/main/sources/originals" target="_blank">GitHub 原始檔 ↗</a></div></div>`}
function transcriptRows(q){return SEED.transcript.filter(s=>!q||s.text.toLowerCase().includes(q.toLowerCase())).map(s=>`<div class="transcript-segment"><button data-seek="${s.start}">${String(Math.floor(s.start/60)).padStart(2,'0')}:${String(Math.floor(s.start%60)).padStart(2,'0')}</button><span data-verbatim>${E(s.text)}</span></div>`).join('')}
function reports(id){const r=R.find(x=>x.id===id);if(r)return heading('MEETING REPORT',r.title,r.summary,btn('開始逐頁報告 ↗','?meeting='+r.id,'blue'))+`<div class="reader prose"><p>${badge(r.date)} ${badge(r.kind||'研究報告','blue')}</p><h2>這次要報告什麼</h2>${paras(r.summary)}${r.slides.map((s,i)=>`<details ${i===0?'open':''}><summary>${String(i+1).padStart(2,'0')}　${E(s.title)}</summary>${s.image?`<img class="media" src="${FILE(s.image)}" alt="${E(s.title)}">`:list(s.bullets||[])}<p style="white-space:pre-wrap">${E(s.speakerNotes||s.notes)}</p><a href="?meeting=${r.id}&slide=${i+1}" target="_blank">從這頁開始報告 ↗</a></details>`).join('')}<button class="button light small" data-edit="report:${r.id}">編輯報告與講稿</button></div>`;return heading('MEETING ROOM','像每次 meeting 一樣，把研究說清楚。','每份報告獨立開窗：逐頁投影片、完整講稿、原始證據與下一步。',`<button class="button blue" id="newReport">＋ 新增研究報告</button>`)+`<div class="grid2">${R.map(reportCard).join('')}</div>`}
const experimentsMeta=[['e7','E7','同樣價量，仍可能有不同折價','2026.10.21','已執行','Chen–Li／Merton 靜態map，校準等價解與噪音敏感性'],['e6','E6','相同觀測，不同真相','2026.10.19','已執行','200 個 seed，額外觀測及 loading 錯設'],['e5','E5','暫時尖峰，還是真實跳躍？','2026.10.15','已執行','凍結選參數、獨立 seed 與六種測試情境'],['e4','E4','流動性公式能算對嗎？','2026.10.15','部分完成','135 組核對；原圖峰值差異尚待釐清'],['e3','E3','平滑成交量能改善未來預測嗎？','2026.10.15','已執行','真實日線、walk-forward 與多重比較校正'],['e2','E2','多一個信用觀測有幫助嗎？','2026.10.15','已執行','toy loading 正確與錯設對照'],['e1','E1','濾波器如何處理兩種尖峰？','2026.10.15','已執行','有標準答案的初步模擬']];
function experiments(id){if(id==='e7')return e7Experiment();if(id&&id!=='e6'){const p={e5:'research/FILTER_HOLDOUT_FINDINGS.md',e4:'research/CHEN2015_REPRODUCTION.md',e3:'research/PILOT_FINDINGS.md',e2:'research/PILOT_FINDINGS.md',e1:'research/PILOT_FINDINGS.md'}[id];return heading('EXPERIMENT '+id.toUpperCase(),experimentsMeta.find(x=>x[0]===id)?.[2]||id,'保留當時的設定、結果與限制。')+`<div class="reader prose" id="onlineDoc" data-path="${p}">正在讀取雲端研究紀錄…</div>`}if(id==='e6'){const s=SEED.e6,max=Math.max(...s.methods.map(x=>x.mean_paired_world_post_event_mse));return heading('EXPERIMENT E6 · 2026.10.19','換濾波器之前，先問資訊夠不夠。','先把問題改成白話：看到同一組數字，我們真的有辦法知道它背後發生了什麼嗎？',btn('逐頁報告 ↗','?meeting=e6','blue'))+e6ReadingPath()+`<div class="grid3"><div class="card">${badge('實驗規模')}<div class="big">200</div><p>獨立 seed，每個含兩個世界<br>固定參數、配對推論、未調參</p></div><div class="card">${badge('已驗證的構造','blue')}<div class="big">相同 y</div><p>兩個世界的單一觀測逐點完全相同，真實狀態不同。</p></div><div class="card">${badge('適用範圍','amber')}<div class="big" style="font-size:26px">合成識別診斷</div><p>額外感測器直接提供狀態資訊。不是新演算法或市場績效。</p></div></div><div class="sectionhead"><h2>第一個實驗：兩種真相，一條相同曲線</h2></div><div class="reader prose"><img class="media" src="${FILE('results/e6_paired_worlds.png')}" alt="E6 配對世界、相同y不同真實狀態與第二觀測"><p>世界 A：狀態真的跳了。世界 B：狀態沒跳，量測被持續污染。y 完全相同，所以任何只看 y 的確定性估計器，都必須給同一個答案；這是資訊限制。</p><div class="formula">yᴬ = xᴬ + ε = xᴮ + b + ε = yᴮ<br>對任意單流輸出 a：<br>½[(a − xᴬ)² + (a − xᴮ)²] ≥ ¼(xᴬ − xᴮ)²</div><p>本構造跳躍後的平均配對 MSE 下界為 <strong>${s.mean_single_stream_post_event_mse_lower_bound.toFixed(4)}</strong>。這個界對所有共用輸出成立；下方 scalar Kalman 只是其中一個實例。</p><h2>第二個實驗：加入資訊，也必須寫對它的意思</h2><p>加入合成觀測 z = x + η，用現成的線性 Kalman 估計 x 與污染 b。正確 loading 能大幅減少誤差；把 loading 寫成 0.5 或負號，則會引入嚴重偏誤。</p><div class="bars">${s.methods.map(m=>`<div class="bar"><span>${E({single_y_kf:'只看 y',dual_correct:'y + 正確 z',dual_loading_half:'z loading 寫成 ½',dual_loading_wrong_sign:'z loading 符號錯'}[m.method])}</span><div class="bartrack"><i class="${m.method.includes('loading')?'bad':''}" style="width:${Math.max(1,m.mean_paired_world_post_event_mse/max*100)}%"></i></div><strong>${m.mean_paired_world_post_event_mse.toFixed(4)}</strong></div>`).join('')}</div><p class="subtle">跳躍後 MSE，越低越好。每個 seed 的兩個世界先平均，再跨 seed 彙總；不把時間點當獨立樣本。</p><div class="callout">主要啟示：額外觀測的資訊與對應關係，可能比換一個 filter 更關鍵。z 是人造的直接狀態感測器，尚未找到真實金融變量來替代它。</div><h2>和論文主線的關係</h2><p>這支持把「識別與觀測設計」放在方法競賽之前，但不證明真實股市也服從這個 toy 模型。下一階段要把教授的定價 map 接上去，檢查真實候選觀測的 Jacobian、條件數與錯設敏感性。</p><h2>推論與可重現性</h2><p>主比較的配對 MSE 差為 ${s.primary.mse_difference_dual_minus_single.toFixed(4)}，95% bootstrap 區間 [${s.primary.mse_difference_percentile_95_ci.map(x=>x.toFixed(4)).join(', ')}]。4800 個 prefix 核對通過。完整 protocol、輸入、程式 hash、逐 seed 結果與負結果保存在線。</p><div class="code">python -m venv .venv<br>pip install -r requirements.txt<br>OPENBLAS_NUM_THREADS=1 .venv/bin/python experiments/run_e6_identifiability.py<br>OPENBLAS_NUM_THREADS=1 .venv/bin/python results/e6_validation_source.py</div><div class="sourcestrip"><a href="#/read/${encodeURIComponent('research/E6_PROTOCOL.md')}">閱讀凍結 protocol</a> · <a href="#/read/${encodeURIComponent('research/E6_FINDINGS.md')}">完整分析</a> · <a href="#/read/${encodeURIComponent('results/e6_summary.json')}">完整統計</a> · <a href="${ARCHIVE}/blob/main/experiments/run_e6_identifiability.py" target="_blank">程式 ↗</a></div></div>`}return heading('EXPERIMENT LOG','讓每個主張，都經過一次檢驗。','先定義要證明什麼，再看結果。成功、失敗與未完成，都保留。')+`<div class="card"><div class="tablewrap"><table class="table"><thead><tr><th>實驗</th><th>研究問題</th><th>狀態</th><th>更新</th><th></th></tr></thead><tbody>${experimentsMeta.map(([id,code,t,date,status,desc])=>`<tr><td>${badge(code,id==='e6'?'blue':'')}</td><td><strong>${t}</strong><div class="subtle">${desc}</div></td><td>${badge(status,status==='部分完成'?'amber':'green')}</td><td class="subtle">${date}</td><td><a href="#/experiments/${id}">閱讀 →</a></td></tr>`).join('')}</tbody></table></div></div><div class="sectionhead"><h2>實驗不是進度百分比</h2></div><div class="grid2"><div class="card"><h3>E3 沒有通過多重比較的預測優勢</h3><p>保留負結果，避免把平滑後的相關當作成功。已看過的資料不能再當成未來方法的最終盲測。</p></div><div class="card"><h3>E5 的改善有清楚失效情境</h3><p>26.57% 僅適用於預先指定的 mixed 合成測試；成串假尖峰、噪音突變與區間覆蓋仍有問題。</p></div></div>`}
function library(){const s=C.sources,items=filter==='all'?Object.values(s).filter(Array.isArray).flat():s[filter]||[];return heading('SOURCE LIBRARY','研究主線之外，還有一張知識地圖。','論文、演講、論壇與程式分開。引用是線索；是否已實作與驗證另外標示。')+`<div class="pillrow">${[['all','全部'],['papers','論文'],['talks','演講'],['forums','論壇'],['code','程式']].map(([k,t])=>`<button class="pill ${filter===k?'active':''}" data-filter="${k}">${t}</button>`).join('')}</div><p class="subtle">${E(filter==='forums'?s.forum_note:s.source_note)} <a href="/workspace" target="_blank">雲端檔案與版本管理 ↗</a> · <a href="${REPO}" target="_blank">GitHub ↗</a></p><input id="sourceSearch" class="search" placeholder="搜尋文獻、作者或研究主題" aria-label="搜尋文獻"><div id="sourceCards" class="grid2">${items.length?items.map(sourceCard).join(''):'<div class="empty">目前沒有已核對的來源；不以未查證資料補滿清單。</div>'}</div>`}
function sourceCard(x){return `<article class="card sourcecard"><div class="subtle">${E(x.authors||x.author||x.type||x.category||'研究來源')} ${E(x.year||'')}</div><h3>${E(x.title||x.name)}</h3>${paras(x.finding||x.summary||x.relevance||x.description||x.already_done)}${x.our_difference?`<div class="callout" style="font-size:12px">與我們的差異：${E(x.our_difference)}</div>`:''}${x.boundary||x.limits||x.status||x.reading_status?`<p>${E(x.boundary||x.limits||x.status||x.reading_status)}</p>`:''}<a class="button ghost small" href="${E(x.url)}" target="_blank" rel="noopener">閱讀來源 ↗</a></article>`}
function meeting(){const q=new URLSearchParams(location.search),id=q.get('meeting'),r=R.find(x=>x.id===id);if(!r){$('#app').innerHTML='<div class="page"><h1>找不到這份報告</h1><a href="/#/reports">回到報告</a></div>';return}let i=Math.max(0,Math.min(r.slides.length-1,(parseInt(q.get('slide'))||1)-1)),s=r.slides[i];document.body.className='meeting-shell';$('#app').innerHTML=`<header class="meeting-top"><a class="subtle" href="/#/reports">← 研究工作站</a><strong>${E(r.title)}</strong><div>${r.pptx?`<a class="button light small" href="${FILE(r.pptx)}">PPTX</a> `:''}<button class="button light small" id="noteToggle">顯示／隱藏講稿</button> <button class="button light small" id="print">列印本頁</button></div></header><div class="meeting-layout"><aside class="thumbnails">${r.slides.map((x,j)=>`<button class="thumb ${i===j?'active':''}" data-slide="${j}"><small>${String(j+1).padStart(2,'0')}</small>${E(x.title)}</button>`).join('')}</aside><section><div class="stage">${s.image?`<img src="${FILE(s.image)}" alt="${E(s.title)}">`:`<div class="eyebrow">${E(s.kicker||r.kind||'RESEARCH MEETING')} · ${String(i+1).padStart(2,'0')}</div><h1>${E(s.title)}</h1>${s.bullets?list(s.bullets):`<p>${E(s.subtitle||'')}</p>`}${s.figure?`<img class="stage-figure" src="${FILE(s.figure)}" alt="${E(s.title)} 圖示">`:''}<div class="source">${E(s.source||r.date+' · Chen Research · 證據與研究提案分開')}</div>`}</div><div class="meeting-controls"><button class="button light small" id="prev" ${i===0?'disabled':''}>← 上一頁</button><span>${i+1} / ${r.slides.length}</span><button class="button light small" id="next" ${i===r.slides.length-1?'disabled':''}>下一頁 →</button></div><article class="speakernotes"><div style="display:flex;justify-content:space-between"><h2>這一頁，我會這樣報告</h2><button id="editNotes" class="button ghost small">編輯講稿</button></div><p>${E(s.speakerNotes||s.notes||'這頁尚未補入講稿。')}</p></article></section></div>`;annotateTerms($('#app'));const go=n=>{q.set('slide',n+1);history.replaceState(null,'','?'+q);meeting()};document.querySelectorAll('[data-slide]').forEach(b=>b.onclick=()=>go(+b.dataset.slide));$('#prev').onclick=()=>go(i-1);$('#next').onclick=()=>go(i+1);$('#print').onclick=()=>window.print();$('#noteToggle').onclick=()=>{$('.speakernotes').hidden=!$('.speakernotes').hidden};$('#editNotes').onclick=()=>{if(!canEdit){login();return}form('編輯本頁講稿',[['title','投影片標題',s.title],['notes','逐字講稿',s.speakerNotes||s.notes,'textarea']],async v=>{const next=structuredClone(R);next.find(x=>x.id===id).slides[i]={...s,title:v.title,speakerNotes:v.notes};await saveReports(next);meeting()})};document.onkeydown=e=>{if($('dialog[open]')||['INPUT','TEXTAREA'].includes(document.activeElement?.tagName))return;if(e.key==='ArrowRight'&&i<r.slides.length-1)go(i+1);if(e.key==='ArrowLeft'&&i>0)go(i-1)};$('.thumb.active')?.scrollIntoView({block:'nearest'});}
async function fileText(p){const res=await fetch(FILE(p)+'&text=1',{cache:'no-store'});if(!res.ok)throw Error('讀取失敗 ('+res.status+')');return res.text()}
async function hydrateDoc(){const d=$('#onlineDoc');if(!d)return;const p=d.dataset.path;try{const t=await fileText(p);if(!document.contains(d))return;d.innerHTML=/\.md$/.test(p)?`<p>${rich(t)}</p>`:`<pre class="code" data-verbatim>${E(t)}</pre>`;annotateTerms(d);}catch(e){d.innerHTML=`<p>雲端檔案暫時無法讀取：${E(e.message)}</p><a href="${ARCHIVE}/blob/main/${E(p)}" target="_blank">在 GitHub 閱讀 ↗</a>`}}
function render(){if(new URLSearchParams(location.search).has('meeting')){meeting();return}const parts=(location.hash.slice(1)||'/home').split('/').filter(Boolean);route=parts[0]||'home';let body;switch(route){case'home':body=home();break;case'learn':body=learning(parts[1]);break;case'manuscript':body=manuscript();break;case'docs':if(parts[2]==='page'){pdfPage=Number(parts[3])||1;docTab='guide';}else if(parts[1]){pdfPage=Number(sessionStorage.getItem('chen-pdf-'+parts[1]))||1;}body=parts[1]==='originals'?originals():parts[1]?paper(parts[1]):documentIndex();break;case'reports':body=reports(parts[1]);break;case'experiments':body=experiments(parts[1]);break;case'library':body=library();break;case'terms':body=termsPage();break;case'read':body=heading('ONLINE READER','研究文件','直接閱讀雲端原文；不需要下載。')+`<div class="reader prose" id="onlineDoc" data-path="${E(decodeURIComponent(parts.slice(1).join('/')))}">正在讀取…</div>`;break;default:route='home';body=home()}shell(body);bind();bindReading();annotateTerms($('#app'));hydrateDoc();window.scrollTo(0,0);}
function bind(){document.querySelectorAll('[data-anchor]').forEach(a=>a.onclick=e=>{e.preventDefault();$('#'+a.dataset.anchor)?.scrollIntoView({behavior:'smooth'})});document.querySelectorAll('[data-doctab]').forEach(b=>b.onclick=()=>{docTab=b.dataset.doctab;const page=pdfPage,y=window.scrollY;render();updatePDF(page);window.scrollTo(0,y);});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render()});$('#sourceSearch')?.addEventListener('input',e=>document.querySelectorAll('.sourcecard').forEach(c=>c.hidden=!c.textContent.toLowerCase().includes(e.target.value.toLowerCase())));const seek=()=>document.querySelectorAll('[data-seek]').forEach(b=>b.onclick=()=>{const a=$('#recording');a.currentTime=+b.dataset.seek;a.play().catch(()=>{})});seek();$('#transcriptSearch')?.addEventListener('input',e=>{$('#transcript').innerHTML=transcriptRows(e.target.value);seek()});$('#newReport')?.addEventListener('click',newReport);}
function form(title,fields,onSave){$('dialog')?.remove();const d=document.createElement('dialog');d.innerHTML=`<form method="dialog"><h2>${E(title)}</h2><p class="subtle">${title==='登入研究工作站'?'登入後可編輯研究主線、課程、論文導讀、報告與逐頁講稿。':'儲存在網站共用雲端並保留歷史版本。原始資料與研究紀錄會保留。'}</p>${fields.map(([name,label,value,type])=>`<label for="field-${name}">${E(label)}</label>${type==='textarea'?`<textarea id="field-${name}" name="${name}">${E(value)}</textarea>`:`<input id="field-${name}" name="${name}" value="${E(value)}" type="${type||'text'}" required>`}`).join('')}<p id="formError" style="color:#b64336;font-size:12px"></p><div class="dialog-actions"><button type="button" class="button light" id="cancel">取消</button><button class="button blue" type="submit">${title==='登入研究工作站'?'登入':'儲存到雲端'}</button></div></form>`;document.body.append(d);d.showModal();$('#cancel').onclick=()=>d.close();d.querySelector('form').onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;const b=d.querySelector('[type=submit]');b.disabled=true;try{await onSave(Object.fromEntries(new FormData(e.target)));d.close();toast('已儲存到共用雲端，版本已保留。')}catch(err){$('#formError').textContent=err.message}finally{busy=false;b.disabled=false}};}
function login(){form('登入研究工作站',[['password','編輯密碼','','password']],async v=>{const r=await fetch('/api/workspace/login',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({password:v.password})});const j=await r.json();if(!r.ok)throw Error(j.error||'登入失敗');canEdit=true;render()});}
async function saveJSON(p,value){const r=await fetch(FILE(p),{method:'PUT',headers:{'content-type':'application/json','x-base-sha256':remoteHash[p]||''},body:JSON.stringify(value,null,2)});const j=await r.json();if(!r.ok)throw Error(j.error||'儲存失敗');remoteHash[p]=j.sha256;}
async function saveContent(v){await saveJSON(PATH,contentForSave(v,SEED.content));C=v;render()}
async function saveReports(v){await saveJSON(REPORTPATH,reportsForSave(v,SEED.reports));R=v;render()}
function editMenu(){form('更新研究主線',[['question','核心研究問題',C.home.question],['abstract','研究摘要',C.home.abstract,'textarea']],async v=>{const n=structuredClone(C);Object.assign(n.home,v);await saveContent(n)})}
function editCurrent(key){if(!canEdit){login();return}if(key==='home'){form('編輯論文主線',[['question','研究問題',C.home.question],['abstract','摘要',C.home.abstract,'textarea'],['introduction','Introduction（段落以空白行分隔）',(C.home.introduction||[]).join('\n\n'),'textarea']],async v=>{const n=structuredClone(C);n.home={...n.home,...v,introduction:v.introduction.split(/\n\s*\n/)};await saveContent(n)})}else if(key.startsWith('lesson:')){const id=key.slice(7),l=C.lessons.find(x=>x.id===id);form('編輯課程',[['title','課程名稱',l.title],['intuition','直覺講解',Array.isArray(l.intuition)?l.intuition.join('\n\n'):l.intuition,'textarea'],['example','數字例子',l.example,'textarea'],['formula','公式',l.formula,'textarea'],['history','歷史與來源',l.history,'textarea'],['pitfalls','容易誤會的地方（一行一項）',l.pitfalls.join('\n'),'textarea'],['relation','如何連回研究',l.relation_to_research,'textarea']],async v=>{const n=structuredClone(C);Object.assign(n.lessons.find(x=>x.id===id),{title:v.title,intuition:v.intuition,example:v.example,formula:v.formula,history:v.history,pitfalls:v.pitfalls.split('\n').filter(Boolean),relation_to_research:v.relation});await saveContent(n)})}else if(key.startsWith('paper:')){const id=key.slice(6),p=C.papers.find(x=>x.id===id);form('編輯核心論文導讀',[['title','論文題名',p.title],['question','核心問題',p.question,'textarea'],...p.sections.flatMap((x,i)=>[['plain'+i,x.title+'：白話理解',x.plain||x.text||x.body,'textarea'],['why'+i,x.title+'：為什麼這樣做',x.why||x.read_for||'','textarea'],['section'+i,x.title+'：技術細節',x.text||x.body,'textarea']])],async v=>{const n=structuredClone(C),q=n.papers.find(x=>x.id===id);q.title=v.title;q.question=v.question;q.sections.forEach((x,i)=>{x.text=v['section'+i];x.body=v['section'+i];x.plain=v['plain'+i];x.why=v['why'+i]});await saveContent(n)})}else if(key.startsWith('report:')){const r=R.find(x=>x.id===key.slice(7));form('編輯報告',[['title','報告標題',r.title],['summary','報告摘要',r.summary,'textarea']],async v=>{const n=structuredClone(R);Object.assign(n.find(x=>x.id===r.id),v);await saveReports(n)})}}
function newReport(){if(!canEdit){login();return}form('新增一次研究 meeting',[['title','報告標題',''],['date','日期',new Date().toLocaleDateString('sv-SE',{timeZone:'Asia/Taipei'}),'date'],['question','這次要回答什麼','', 'textarea'],['method','做了什麼與證據來源','', 'textarea'],['finding','結果、失敗與下一步','', 'textarea']],async v=>{const id='meeting-'+Date.now(),slides=[{title:v.title,bullets:[v.question],speakerNotes:v.question},{title:'這次怎麼做',bullets:[v.method],speakerNotes:v.method},{title:'結果與下一步',bullets:[v.finding],speakerNotes:v.finding}];await saveReports([{id,title:v.title,date:v.date,summary:v.question,kind:'研究進度',slides},...R])})}
async function init(){render();try{const results=await Promise.all([fetch(FILE(PATH),{cache:'no-store'}),fetch(FILE(REPORTPATH),{cache:'no-store'}),fetch('/api/workspace/session',{cache:'no-store'})]);for(let i=0;i<2;i++){const r=results[i];if(r.ok){const v=await r.json();remoteHash[i===0?PATH:REPORTPATH]=r.headers.get('x-file-sha256');if(i===0)C=loadContent(SEED.content,SEED.baseContent,v);else R=loadReports(SEED.reports,SEED.baseReports,v);}}if(results[2].ok)canEdit=Boolean((await results[2].json()).canEdit);render()}catch(e){toast('目前顯示已部署版本，雲端即時讀取暫不可用。')}}
window.addEventListener('hashchange',()=>{if(location.hash.startsWith('#/'))render()});init();
function lessonVisual(l){const v=l.visual;if(!v)return'';let out='';if(v.type==='flow'||v.type==='comparison'){out=`<div class="researchflow" style="grid-template-columns:repeat(${(v.steps||v.columns).length},minmax(0,1fr))">${(v.steps||v.columns).map((x,i)=>`<div><span class="eyebrow">0${i+1}</span><br><strong>${E(x)}</strong></div>`).join('')}</div>`;}else if(v.type==='series'){out=`<svg viewBox="0 0 660 200" style="width:100%" role="img" aria-label="短暫假尖峰與持續真跳躍：前三點相同，後來才分開"><path d="M40 150H620 M40 40V150" stroke="#ddd" fill="none"/><path d="M55 135L190 135L325 45L460 135L595 135" fill="none" stroke="#c18b41" stroke-width="3"/><path d="M55 135L190 135L325 45L460 45L595 45" fill="none" stroke="#0071e3" stroke-width="3" stroke-dasharray="7 5"/><text x="410" y="30" fill="#0071e3" font-size="12">持續真跳躍</text><text x="420" y="165" fill="#9c6700" font-size="12">短暫假尖峰</text><text x="80" y="190" fill="#73737b" font-size="11">共同前綴：即時看到第 3 點，還無法知道後續。</text></svg>`;}out+=`<p class="subtle">${E(v.caption)}（教學示意）</p>`;if(l.id==='L5')out+=`<div class="callout"><strong>動手調整：今天的讀數有多可靠？</strong><p>模型預測 3.0%，今天讀到 3.8%。預測變異數 P⁻ = 1，拖動量測變異數 R。</p><label for="noiseSlider" class="subtle">量測噪音 R：<output id="noiseValue">1.0</output></label><input id="noiseSlider" type="range" min="0.1" max="9" step="0.1" value="1" style="width:100%;accent-color:var(--blue)"><p id="kalmanValue" style="font-size:20px;color:var(--blue)">K = 0.50 → 更新利率 = 3.40%</p><small class="subtle">R 越大，越少相信今天的讀數。此為單變量教學，不是 CIR 原論文估計。</small></div>`;return out;}
document.addEventListener('input',e=>{if(e.target.id==='noiseSlider'){const r=+e.target.value,k=1/(1+r);$('#noiseValue').textContent=r.toFixed(1);$('#kalmanValue').textContent=`K = ${k.toFixed(2)} → 更新利率 = ${(3+k*.8).toFixed(2)}%`;}});
function pdfReaderHTML(p,pdf){const pages=p.page_images||[];pdfPage=Math.max(1,Math.min(pages.length||1,pdfPage));const related=sectionForPage(p,pdfPage);return `<section class="pdf-reader"><div class="pdf-controls"><button class="button light small" id="pdfPrev" aria-label="原文上一頁" ${pdfPage===1?'disabled':''}>←</button><label for="pdfPageSelect">第 <select id="pdfPageSelect" aria-label="原文頁碼">${pages.map((_,i)=>`<option value="${i+1}" ${pdfPage===i+1?'selected':''}>${i+1} / ${pages.length}</option>`).join('')}</select> 頁</label><button class="button light small" id="pdfNext" aria-label="原文下一頁" ${pdfPage===pages.length?'disabled':''}>→</button><label for="pdfZoom">縮放 <select id="pdfZoom">${[100,125,150,175,200].map(z=>`<option value="${z}" ${z===pdfZoom?'selected':''}>${z}%</option>`).join('')}</select></label></div><div class="pdf-context" aria-live="polite"><span>這頁看什麼：${E(related?.title||'補充頁面，請對照上下文')}</span>${related?'<button id="guideForPage">定位左側導讀 ←</button>':''}</div><div class="pdf-page-viewport" tabindex="0" aria-label="可捲動的原文頁面">${pages.length?`<img class="pdf-page-img" style="width:${pdfZoom}%" src="${FILE(pages[pdfPage-1])}" alt="${E(p.title)} 原始 PDF 第 ${pdfPage} 頁">`:`<iframe class="pdf" title="${E(p.title)}" src="${FILE('sources/originals/'+pdf)}#page=${pdfPage}"></iframe>`}<details class="pdf-text"><summary>這一頁的擷取文字（輔助閱讀）</summary><p>擷取可能有誤，公式請對照頁面。</p><pre data-verbatim>${E(p.page_text?.[pdfPage-1]||'此頁沒有可擷取文字。')}</pre></details></div></section>`}
function researchMap(){return `<div class="map-line"></div><div class="map-node observation"><span>01 / 看得到的</span><strong>價格與成交量</strong><svg viewBox="0 0 220 60" aria-label="起伏讀數的教學示意"><path d="M2 46L20 39L30 48L43 12L55 37L68 33L81 40L96 25L108 34L121 8L134 29L146 20L159 31L173 17L185 23L200 8L218 15"/></svg><small>一條線，可能有不同解釋</small></div><div class="map-node question"><span>02 / 真正想問</span><strong>是雜訊，還是真變化？</strong><small>先問資訊夠不夠，再選方法</small><div class="map-pills"><b>減少異常讀數</b><b>保留市場事件</b></div></div><div class="map-node evidence"><span>03 / 用什麼回答</span><strong>模型 ＋ 可重跑實驗</strong><small>也留下失敗，才知道結論走多遠</small></div><div class="map-orbit" aria-hidden="true">?</div>`}
function storySteps(){return `<ol class="logic-steps">${[
 ['先定義問題','教授希望先看清成交量，再研究價量關係。錄音另提出流動性定價方向；這兩層目標要連接，但不能混成同一個已成立的結論。','原始訊息與錄音','#/docs/originals'],
 ['找到可借用的兩塊拼圖','利率論文教我們如何由多個讀數估計隱藏狀態；流動性論文提供交易受限時的定價目標。兩篇之間，還缺一座經過檢驗的動態橋梁。','兩篇論文並排導讀','#/docs'],
 ['先測簡單方法，也保留失敗','我們先比較濾波與預測。第三個實驗沒有校正後的正向預測勝出者；第五個實驗在指定模擬中改善，換成成串假尖峰卻失效。','實驗 E1–E5 與負結果','#/experiments'],
 ['追問：是方法不夠好，還是資訊不夠？','第六個實驗刻意讓兩種不同真相產生相同讀數。只看這份資料的工具無法分辨；加入正確的額外讀數才有幫助。','實驗 E6 的設計與結果','#/experiments/e6'],
 ['下一步才接上經濟模型','確認原公式與觀測的意義，再檢查價格、成交量及信用資訊能否分開不同原因。這一步尚未完成；完成前，不宣稱估到了市場真實流動性。','待解問題與停止條件','#/manuscript']
 ].map(([title,text,label,href],i)=>`<li><span class="step-number">0${i+1}</span><div><h3>${title}</h3><p>${text}</p><a class="text-link" href="${href}">${label} →</a></div></li>`).join('')}</ol>`}
function researchReasoning(){return `<details class="reasoning-map" open><summary>先讀這張推理地圖：為什麼我們這樣研究？</summary><div class="reasoning-intro"><p>每一層都必須回答前一層留下的問題。這裡的研究順序是我們的規劃，不是教授已經證明的結論。</p></div>${storySteps()}<div class="claim-key"><span>原始來源：教授實際提出什麼</span><span>本次實驗：我們實際檢驗什麼</span><span>研究提案：還需要證明什麼</span></div></details>`}
function annotateTerms(root){if(!root||!explainOn)return;const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);const nodes=[];while(w.nextNode()){const n=w.currentNode;if(!n.textContent.trim()||n.parentElement.closest('.term,[data-verbatim],input,textarea,select,option,pre,code,svg,.formula,.code,.eyebrow,nav,.sidefoot,.paper-citation,.pane-header,.pdf-controls,.pdf-context,.reader-footnote,.workbench-toolbar,.badge,.rindex'))continue;nodes.push(n)}const seenBlocks=new WeakMap();for(const n of nodes){if(!n.isConnected)continue;const scope=n.parentElement.closest('p,li,h1,h2,h3,figcaption,td,.callout,.bar,blockquote')||n.parentElement;let seen=seenBlocks.get(scope);if(!seen){seen=new Set();seenBlocks.set(scope,seen)}const heading=n.parentElement.closest('h1,h2,h3');const parts=explainParts(n.textContent,seen).map(part=>heading&&part.id&&!/[A-Za-z]/.test(part.text)?{text:part.text}:part);if(!parts.some(p=>p.id))continue;const fragment=document.createDocumentFragment();for(const part of parts){if(!part.id){fragment.append(document.createTextNode(part.text));continue}const span=document.createElement('span');span.className='term';const canClick=!n.parentElement.closest('a,button,summary,label');const word=document.createElement(canClick?'button':'span');word.className='term-word';word.textContent=part.text;if(canClick){word.type='button';word.dataset.term=part.id;word.setAttribute('aria-label',part.text+'：'+part.meaning+'，開啟例子');}span.append(word);const meaning=document.createElement('span');meaning.className='term-meaning';meaning.textContent='（'+part.meaning+'）';span.append(meaning);fragment.append(span)}n.replaceWith(fragment)}}
function openTerm(id){const t=TERMS.find(x=>x.id===id);if(!t)return;$('#termDialog')?.remove();const d=document.createElement('dialog');d.id='termDialog';d.setAttribute('aria-labelledby','termTitle');d.className='term-dialog';d.innerHTML=`<div class="term-dialog-top"><span class="eyebrow">在原地弄懂，不用離開文章</span><button class="icon-button" id="closeTerm" aria-label="關閉名詞解釋">×</button></div><h2 id="termTitle">${E(t.id)}</h2><p class="term-lead">${E(t.meaning)}</p><h3>用一個例子理解</h3><p>${E(t.example)}</p><h3>為什麼出現在我們的研究裡？</h3><p>${E(t.relation)}</p><a class="button light" href="#/terms" id="allTerms">看所有名詞 →</a>`;document.body.append(d);d.showModal();$('#closeTerm').onclick=()=>d.close();$('#allTerms').onclick=()=>d.close();d.addEventListener('click',e=>{if(e.target===d)d.close()});}
function termsPage(){return heading('READING COMPANION','不懂的詞，就在這裡停一下。','閱讀中點有底線的詞，也能原地看例子。括號解釋預設開啟，原始引文與論文頁面保持原樣。')+`<input class="search" id="termSearch" type="search" placeholder="例如：MS、流動性、MSE、Kalman" aria-label="搜尋名詞"><div class="term-catalog grid2" data-verbatim>${TERMS.map(t=>`<article class="card term-card" data-search="${E([t.id,...t.aliases,t.meaning,t.example].join(' ').toLowerCase())}"><span class="eyebrow">READING NOTE</span><h2 id="termTitle">${E(t.id)}</h2><p class="term-lead">${E(t.meaning)}</p><h3>用例子想</h3><p>${E(t.example)}</p><h3>連回研究</h3><p>${E(t.relation)}</p></article>`).join('')}</div><p id="termEmpty" class="empty" hidden>目前找不到這個詞。可以用中文意思或英文縮寫試試。</p>`}
function updatePDF(page){const pane=$('.paper-workbench');if(!pane)return;const p=C.papers.find(x=>x.id===pane.dataset.paperId);if(!p)return;pdfPage=Math.max(1,Math.min(p.page_images.length,Number(page)||1));sessionStorage.setItem('chen-pdf-'+p.id,pdfPage);const pdf=C.papers.indexOf(p)===0?'jrefe_galley.pdf':'JFI-CHEN.pdf';$('#pdfPanel').innerHTML=pdfReaderHTML(p,pdf);$('.original-pane .pane-header span').innerHTML=`<i class="dot amber"></i> 原始 PDF · 頁序 ${pdfPage}/${p.pdf_page_count}`;document.querySelectorAll('[data-pdf-page]').forEach(b=>b.classList.toggle('selected',+b.dataset.pdfPage===pdfPage));document.querySelectorAll('.guide-section[data-pages]').forEach(el=>el.classList.toggle('is-current',el.dataset.pages.split(',').includes(String(pdfPage))));bindPDF();}
function bindPDF(){const p=C.papers.find(x=>x.id===$('.paper-workbench')?.dataset.paperId);if(!p)return;$('#pdfPageSelect')?.addEventListener('change',e=>updatePDF(+e.target.value));$('#pdfPrev')?.addEventListener('click',()=>updatePDF(pdfPage-1));$('#pdfNext')?.addEventListener('click',()=>updatePDF(pdfPage+1));$('#pdfZoom')?.addEventListener('change',e=>{pdfZoom=+e.target.value;const img=$('.pdf-page-img');if(img)img.style.width=pdfZoom+'%'});$('#guideForPage')?.addEventListener('click',()=>{const section=sectionForPage(p,pdfPage),idx=p.sections.indexOf(section);if(idx<0)return;if(docTab==='impact'){docTab='guide';const n=pdfPage;render();updatePDF(n)}const target=$('#guide-'+idx),scroller=$('.guide-scroll');if(target&&scroller)scroller.scrollTo({top:target.offsetTop-scroller.offsetTop-20,behavior:'smooth'});});}
function bindReading(){bindPDF();document.querySelectorAll('[data-pdf-page]').forEach(b=>b.onclick=()=>{updatePDF(+b.dataset.pdfPage);const raw=$('.pdf-page-viewport');raw?.scrollTo(0,0);});document.querySelectorAll('[data-layout]').forEach(b=>b.onclick=()=>{paperLayout=b.dataset.layout;const pane=$('.paper-workbench');pane.className='paper-workbench layout-'+paperLayout;document.querySelectorAll('[data-layout]').forEach(x=>{x.classList.toggle('active',x.dataset.layout===paperLayout);x.setAttribute('aria-pressed',x.dataset.layout===paperLayout)})});$('#termSearch')?.addEventListener('input',e=>{let count=0;document.querySelectorAll('.term-card').forEach(c=>{c.hidden=!c.dataset.search.includes(e.target.value.toLowerCase());if(!c.hidden)count++});$('#termEmpty').hidden=count>0});}
document.addEventListener('click',e=>{const b=e.target.closest('[data-term]');if(b)openTerm(b.dataset.term)});

function renderReadingPosition(){const y=window.scrollY,left=$('.guide-scroll')?.scrollTop||0,right=$('.pdf-page-viewport')?.scrollTop||0;render();window.scrollTo(0,y);if($('.guide-scroll'))$('.guide-scroll').scrollTop=left;if($('.pdf-page-viewport'))$('.pdf-page-viewport').scrollTop=right;}

function e6ReadingPath(){return `<section class="reader prose experiment-story"><div class="eyebrow">先懂這次為什麼做，再看數字</div><h2>第五個實驗留給我們一個疑問。</h2><p>當錯誤讀數持續很多期，估計工具會把它誤認為市場真的改變。這時多試一個方法，可能仍在回答錯問題：資料本身究竟有沒有留下足夠線索？</p><div class="experiment-questions"><div><span>我們刻意控制什麼</span><p>造出兩個背後真相不同、但看到的數字完全相同的世界。讓方法拿到一模一樣的輸入。</p></div><div><span>這能檢驗什麼</span><p>若輸入相同，固定方法只能給相同答案。因此它不可能在兩個不同真相上都完全答對。</p></div><div><span>接著改變什麼</span><p>加入一支直接提供狀態線索的合成感測器，再把它的對應關係故意寫錯，檢查額外資訊何時有幫助。</p></div></div><details><summary>看圖與公式之前：每個符號代表什麼？</summary><dl class="symbol-list"><dt>x</dt><dd>我們想找回的真實狀態；在模擬裡先知道答案。</dd><dt>y</dt><dd>方法原本看得到的讀數；兩個世界逐點完全相同。</dd><dt>b</dt><dd>讓讀數偏掉的持續污染。</dd><dt>z</dt><dd>額外提供的讀數；這次人為設定它直接反映 x。</dd><dt>ε、η</dt><dd>各讀數的隨機誤差。</dd><dt>a</dt><dd>只使用相同 y 時，方法給出的共用估計。</dd><dt>MSE</dt><dd>均方誤差：把估計和真實答案的差平方，再取平均，越小越好。</dd></dl></details><p class="subtle">這是用來診斷資訊限制的模擬。找到金融市場中可信的第二份觀測，是下一階段的工作。</p></section>`}

function e7Experiment(){const s=SEED.e7;return heading('EXPERIMENT E7 · 2026.10.21','同樣的價量，為什麼仍可能估出不同折價？','E6之後，我們把問題接到教授提供的公式；先查能分辨什麼，再談濾波。',btn('逐頁報告與講稿 ↗','?meeting=e7','blue'))+`<section class="reader prose experiment-story"><h2>先把「換算比例」想清楚。</h2><p>兩位醫師看到同樣的溫度與心跳，但若儀器換算比例也能任意改，仍可能推出不同病況。多一份讀數能否幫忙，取決於它與目標之間的關係是否可靠。</p><p>這次的讀數是合成股權價格與成交量。價量基準的斜率 b 也跟著候選解改變時，找到41組不同狀態：讀數相同，資產折價卻約5.41至15.59。這不是市場金額或信賴區間。</p><details><summary>先看懂這一頁的幾個符號與數字</summary><dl class="symbol-list"><dt>b</dt><dd>假設的價量基準線有多斜；價格改一點，基準成交量會改多少。這個換算關係本身也可能未知。</dd><dt>K</dt><dd>這個put例子的履約價，決定到期給付的轉折位置；不能直接當成市場流動性的真值。</dd><dt>log</dt><dd>對數轉換，讓數值比較較接近比例變化。這次log狀態誤差不直接等於金額誤差。</dd><dt>數值滿秩</dt><dd>在測試精度下，兩份讀數對兩種狀態提供可區分的方向；不代表所有情況都只有唯一答案。</dd><dt>條件數</dt><dd>反推對誤差有多敏感的診斷數字。越大，微小讀數誤差越可能造成很大的狀態差異。</dd><dt>多起點</dt><dd>換幾個不同的初始猜測再求解，檢查結果是否依賴從哪裡開始。</dd><dt>觸界</dt><dd>解停在事先允許範圍的上限或下限，提醒我們點估計可能不穩或受範圍限制。</dd></dl></details><h2>這次接了哪三條公式？</h2><div class="formula">基本面 V、給付履約價 K<br>↓ Chen–Li put 給付公式<br>資產 A、A*<br>↓ Merton 股權關係<br>股權 E、E*<br>↓ 假定的價量基準 Q_vol = a − bE<br>觀察 E* 與 Q_vol，反推 V、K</div><p>V不是成交量；K是給付形狀，尚不能直接稱為純流動性。固定μ=.6、r=.05、σ=.8、一年到期，Merton債務10與波動.3，a=2、b=.01。這些是合成設定，沒有任何公司實際債務或成交股數。</p><div class="callout">本次沿用 E4 對作者草稿公式的明示解讀。R符號與Exhibit 2B原圖差異仍未解決，不能稱為教授全文或市場實證重現。</div><h2>1．多一份讀數，仍可能只有很弱的線索。</h2><p>${s.grid_points}個網格全部可計算，${s.full_numeric_rank_points}個通過預先設定的數值滿秩門檻；條件數中位數約${s.condition_median.toFixed(2)}。這表示某些狀態變化在觀測上非常相似，噪音可能被放大。</p><img class="media" src="${FILE('results/e7/conditioning.png')}" alt="E7 定價映射的局部條件數：部分區域弱敏感度，青色為數值奇異點"><p class="subtle">亮色代表較難穩定區分；青色格是差分最小奇異值為零的一點。局部數值秩與有限精度檢查，不等於精確代數、跨期或全域識別證明。</p><h2>2．基準 b 自由時，相同讀數容許不同折價。</h2><img class="media" src="${FILE('results/e7/equivalent_worlds.png')}" alt="41個不同V、K、b，重建相同股權價格與成交量，但折價不同"><p>固定(V,K)=(100,100)的參考價量，再逐一改變K、求同股權價格的V，最後反推b使成交量也相同。41點全部找到根，b約.00789至.01397，資產折價約<strong>${s.profile_discount_min.toFixed(2)}–${s.profile_discount_max.toFixed(2)}</strong>，最大價量log重建誤差約9.09e−13。</p><p>這是一條找到的等價解曲線，不是完整解集合的邊界，也不是信賴區間。「兩個讀數配兩個狀態」會漏掉同樣未知的校準參數。</p><h2>3．無噪音也可能擬合完美、狀態有偏。</h2><div class="tablewrap"><table class="table"><thead><tr><th>假定b／真b</th><th>log狀態MSE</th><th>折價相對平方誤差</th></tr></thead><tbody>${s.noiseless_by_b.map(x=>`<tr><td>${x.b_scale}</td><td>${x.log_state_mse<1e-10?x.log_state_mse.toExponential(2):x.log_state_mse.toFixed(6)}</td><td>${x.discount_relative_sq_error<1e-10?x.discount_relative_sq_error.toExponential(2):x.discount_relative_sq_error.toFixed(6)}</td></tr>`).join('')}</tbody></table></div><p>三組價量損失都接近機器精度，卻只有正確b恢復真值。表中是平方誤差，不能直接讀成價格誤差百分比。</p><h2>4．正確基準，也不保證有噪音時穩定。</h2><p>30個新seed、每seed四真值；價格log噪音標準差.02、量log噪音.05，各設定共用同一份噪音。先在每seed平均四真值，再跨seed平均。</p><div class="tablewrap"><table class="table"><thead><tr><th>假定b／真b</th><th>log狀態MSE</th><th>折價相對平方誤差</th><th>觸界／120次</th></tr></thead><tbody>${s.noisy_by_b.map(x=>`<tr><td>${x.b_scale}</td><td>${x.mean_log_state_mse.toFixed(6)}</td><td>${x.mean_discount_relative_sq_error.toFixed(6)}</td><td>${x.selected_boundary_count}</td></tr>`).join('')}</tbody></table></div><p>正確b也有46/120次最佳解碰到參數界。高估b的描述性誤差反而略低；這個負結果保留，不做顯著性或新方法優勝主張。</p><h2>這使下一個實驗怎麼改？</h2><p>先約束a、b、債務與波動等參數，弱識別時提供敏感性集合，再檢查跨期資訊能補多少。之後才讓不同濾波器使用相同資訊比較；不能把自由校準吸收的差異命名為唯一流動性。</p><h2>資料與重跑</h2><p>143個網格、41個等價點、124筆觀測、1548個起點fit、372個選解全部保存。四真值另對獨立積分，最大差約3.02e−14；隔離目錄完整重跑的數值檔hash相同。首次摘要寫出因無限值JSON序列化失敗，原始數值保留；只修表示法，未改設定或選結果。</p><div class="code">OPENBLAS_NUM_THREADS=1 .analysis-env/bin/python experiments/run_e7_pricing_identifiability.py --output /tmp/chen-e7-rerun<br>OPENBLAS_NUM_THREADS=1 .analysis-env/bin/python research/e7/validate.py</div><div class="sourcestrip"><a href="#/read/${encodeURIComponent('research/e7/PROTOCOL.md')}">固定規劃</a> · <a href="#/read/${encodeURIComponent('research/e7/FINDINGS.md')}">完整分析</a> · <a href="#/read/${encodeURIComponent('results/e7/summary.json')}">數字摘要</a> · <a href="#/read/${encodeURIComponent('results/e7/validation.json')}">獨立驗證</a> · <a href="${FILE('experiments/run_e7_pricing_identifiability.py')}">程式</a></div></section>`}
